/**
 * The shared revocation-statement table (`tests/fixtures/revocation-statement/cases.json`),
 * generated by the delivery side's registry tests and read by all four bindings:
 * which signed revocation statements count (`docs/guides/fetch-v1.md`,
 * "Build-level revocation", rule 5), and that the first verifying revocation in a
 * listing wins. The statement rows call `verifyRevocation`; the listing rows drive
 * the real candidate loop through `checkInstalled` against a local registry.
 */

import { createHash } from 'node:crypto';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import * as http from 'node:http';
import type { AddressInfo } from 'node:net';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { useProdV2ForTests } from '../../src/ocifetch/channel.js';
import { MEDIA_TYPE_BUNDLE, MEDIA_TYPE_INDEX, MEDIA_TYPE_MANIFEST, REVOCATION_ARTIFACT_TYPE } from '../../src/ocifetch/constants.gen.js';
import { keyIdOfRawKey } from '../../src/ocifetch/dsse.js';
import { checkInstalled } from '../../src/ocifetch/ensure.js';
import { ArtifactRevokedError } from '../../src/ocifetch/errors.js';
import type { Advisory } from '../../src/ocifetch/errors.js';
import { resetRevocationMemoForTests, revokedText, verifyRevocation } from '../../src/ocifetch/revocation.js';
import type { RevocationSubject } from '../../src/ocifetch/revocation.js';
import type { Clock, Resolved } from '../../src/ocifetch/types.js';

interface WireAdvisory {
  readonly id: string;
  readonly url: string;
  readonly class: string;
  readonly summary: string;
  readonly superseded_by: string;
  readonly revoked_at: string;
}
interface StatementCase {
  readonly name: string;
  readonly bundle: string;
  readonly expect: 'verifies' | 'ignored';
  readonly expect_advisory?: WireAdvisory;
}
interface ListingCase {
  readonly name: string;
  readonly referrers: readonly string[];
  readonly expect: 'revoked' | 'fail-open';
  readonly expect_advisory?: WireAdvisory;
  readonly ignored: readonly string[];
  readonly dont_care?: readonly string[];
}

const DIR = fileURLToPath(new URL('../../../tests/fixtures/revocation-statement/', import.meta.url));
const present = existsSync(path.join(DIR, 'cases.json'));
const doc = present
  ? (JSON.parse(readFileSync(path.join(DIR, 'cases.json'), 'utf8')) as { cases: StatementCase[]; listings: ListingCase[] })
  : { cases: [] as StatementCase[], listings: [] as ListingCase[] };
const build = present
  ? (JSON.parse(readFileSync(path.join(DIR, 'build.predicate.json'), 'utf8')) as { manifest: string; layer: string; predicate: Record<string, unknown> })
  : { manifest: '', layer: '', predicate: {} };
const keyHex = present ? readFileSync(path.join(DIR, 'key.pub.hex'), 'utf8').trim() : '';
const keys = [{ keyid: present ? keyIdOfRawKey(keyHex) : '', ed25519Hex: keyHex }];

const sha = (b: Buffer | string): string => `sha256:${createHash('sha256').update(b).digest('hex')}`;
const wire = (a: Advisory): WireAdvisory => ({ id: a.id, url: a.url, class: a.class, summary: a.summary, superseded_by: a.supersededBy, revoked_at: a.revokedAt });
const bundleOf = (name: string): Buffer => readFileSync(path.join(DIR, name));

describe('the shared revocation-statement table (tests/fixtures/revocation-statement/cases.json)', () => {
  it('is beside this checkout and has rows', (ctx) => {
    if (!present) ctx.skip('SKIPPED: the shared revocation-statement table is not beside this checkout');
    expect(doc.cases.length).toBeGreaterThan(0);
    expect(doc.listings.length).toBeGreaterThan(0);
    expect(doc.cases.some((c) => c.expect === 'verifies')).toBe(true);
    expect(doc.listings.some((l) => l.expect === 'revoked')).toBe(true);
  });

  const sub: RevocationSubject = {
    manifest: build.manifest,
    layer: build.layer,
    predicate: build.predicate,
    version: '26.8.15.10',
    platform: 'linux-amd64',
    build: '20260101.000000',
    request: '26.8',
    dir: '',
    writable: false,
  };

  for (const c of doc.cases) {
    it(`statement: ${c.name}`, () => {
      const v = verifyRevocation(bundleOf(c.bundle), keys, sub);
      if (c.expect === 'ignored') {
        expect('revocation' in v, `${c.name} verifies, want it refused`).toBe(false);
        if ('reason' in v) expect(v.reason).not.toBe('');
        return;
      }
      if (!('revocation' in v)) throw new Error(`${c.name} does not verify (${v.reason})`);
      expect(v.revocation.advisories.length).toBe(1);
      expect(wire(v.revocation.advisories[0]!)).toEqual(c.expect_advisory);
      const hasFix = c.expect_advisory!.superseded_by !== '';
      expect(revokedText(sub, v.revocation).includes('; superseded by build ')).toBe(hasFix);
    });
  }
});

interface Served {
  readonly base: string;
  readonly byFile: Map<string, string>;
  readonly close: () => Promise<void>;
}

/** Serves one build's referrers listing in order, each referrer's manifest and bundle. */
async function serveListing(referrers: readonly string[]): Promise<Served> {
  const objects = new Map<string, Buffer>();
  const byFile = new Map<string, string>();
  const manifests: Record<string, unknown>[] = [
    // The listing must name a signature referrer, or the status is unread.
    { mediaType: MEDIA_TYPE_MANIFEST, digest: sha('signature'), size: 9, artifactType: MEDIA_TYPE_BUNDLE },
  ];
  for (const name of referrers) {
    const bundle = bundleOf(name);
    const layer = { mediaType: MEDIA_TYPE_BUNDLE, digest: sha(bundle), size: bundle.length };
    const body = Buffer.from(
      JSON.stringify({
        schemaVersion: 2,
        mediaType: MEDIA_TYPE_MANIFEST,
        artifactType: REVOCATION_ARTIFACT_TYPE,
        config: { mediaType: 'application/vnd.oci.empty.v1+json', digest: sha('{}'), size: 2 },
        layers: [layer],
      }),
    );
    const digest = sha(body);
    byFile.set(name, digest);
    objects.set(`/manifests/${digest}`, body);
    objects.set(`/blobs/${layer.digest}`, bundle);
    manifests.push({ mediaType: MEDIA_TYPE_MANIFEST, digest, size: body.length, artifactType: REVOCATION_ARTIFACT_TYPE });
  }
  objects.set(`/referrers/${build.manifest}`, Buffer.from(JSON.stringify({ schemaVersion: 2, mediaType: MEDIA_TYPE_INDEX, manifests })));
  const server = http.createServer((req, res) => {
    for (const [suffix, body] of objects) {
      if ((req.url ?? '').endsWith(suffix)) {
        res.writeHead(200, { 'Content-Length': body.length });
        res.end(body);
        return;
      }
    }
    res.writeHead(404, { 'Content-Length': 0 });
    res.end();
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address() as AddressInfo;
  return {
    base: `http://127.0.0.1:${port}/chtypes/v2`,
    byFile,
    close: async () => {
      server.closeAllConnections();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

const clock: Clock = { now: () => Date.now(), sleep: async () => {} };

describe.skipIf(!present)('the shared revocation-statement table: listings through checkInstalled', () => {
  let restore: () => void;
  let cache: string;
  beforeEach(() => {
    restore = useProdV2ForTests();
    resetRevocationMemoForTests();
    cache = mkdtempSync(path.join(tmpdir(), 'chtypes-revstmt-'));
  });
  afterEach(() => {
    resetRevocationMemoForTests();
    restore();
    rmSync(cache, { recursive: true, force: true });
  });

  for (const l of doc.listings) {
    it(l.name, async () => {
      const served = await serveListing(l.referrers);
      try {
        const res = {
          abiGeneration: 2,
          platform: 'linux-amd64',
          request: '26.8',
          version: '26.8.15.10',
          build: '20260101.000000',
          libraryPath: '',
          dir: '',
          digests: { manifest: build.manifest, layer: build.layer, bundle: '' },
          predicate: build.predicate,
          signedBy: '',
          source: 'cache',
          alreadyInstalled: true,
          warnings: [],
        } as unknown as Resolved;
        const { warnings, error } = await checkInstalled(res, { bases: [served.base], cacheDir: cache, systemDirs: [], trustedKeys: keys, clock });

        const ignored = l.ignored.map((f) => served.byFile.get(f)!);
        const dontCare = (l.dont_care ?? []).map((f) => served.byFile.get(f)!);
        for (const d of ignored) {
          expect(
            warnings.some((w) => w.includes(d) && w.includes('does not verify and is ignored')),
            `no warning names ignored referrer ${d}: ${JSON.stringify(warnings)}`,
          ).toBe(true);
        }
        for (const w of warnings) {
          expect(w).toContain('does not verify and is ignored');
          expect([...ignored, ...dontCare].some((d) => w.includes(d)), `warning names no listed referrer: ${w}`).toBe(true);
        }

        if (l.expect === 'revoked') {
          expect(error, 'the build was allowed, want CHTYPES_ARTIFACT_REVOKED').toBeInstanceOf(ArtifactRevokedError);
          const rev = (error as ArtifactRevokedError).revocation;
          expect(rev.signed).toBe(true);
          expect(rev.advisories.length).toBe(1);
          expect(wire(rev.advisories[0]!)).toEqual(l.expect_advisory);
        } else {
          expect(error, 'the build was refused, want it allowed').toBeUndefined();
        }
      } finally {
        await served.close();
      }
    });
  }
});
